import{z as A,x as B,o as l,c as d,q as o,j as r,D as E,d as t,s,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"指令选择","description":"","frontmatter":{"title":"指令选择","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cg-instruction-selection.md","filePath":"cs/cg-instruction-selection.md","lastUpdated":1791063341000}'),c={name:"cs/cg-instruction-selection.md"};function p(h,a,D,m,C,f){const i=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=o('<h1 id="指令选择" tabindex="-1">指令选择 <a class="header-anchor" href="#指令选择" aria-label="Permalink to &quot;指令选择&quot;">​</a></h1><div class="epigraph"><p>选择器问的是：用这台机器的封闭指令集，盖住这棵开放的计算图，总价最小。树可以动态规划，图就要讲和了。</p><footer>—— 据 Aho, Ganapathi and Tjiang, 1989；Ertl, POPL, 1997 整理</footer></div><p><a href="/cs/cg-register-allocation-deep">上一课</a>把分配算成代价账：溢出谁、溢出成什么样、ABI 在哪里夹住它。但分配分的是已经存在的值；值本身由哪些指令、几条指令算出来，是更上游的决定——同一个 <code>a+b*4</code>，在 x86-64 上可以是一条 <code>lea</code>，也可以是一条移位加一条加法。<a href="/cs/instruction-select">指令选择</a>给过覆盖的画面，<a href="/cs/tree-pattern-isel">树匹配指令选择</a>给过树上动态规划；本课补剩下的三块：模式从哪来、图怎么办、选择与分配怎么互相拉扯。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IR 的词汇是开放的：任意宽的整数、任意嵌套的表达式；目标指令集是封闭的。选择就是用封闭词汇覆盖开放词汇，约束是语义等价，目标是总代价最小。树上有最优解：对每个节点枚举以它为根的 tile，子问题重叠，自底向上动态规划。三个麻烦随后到来。其一，真实程序是 DAG 不是树：<a href="/cs/available-expr">可用表达式</a>留下的共享节点若被两个 tile 分别盖住，就计算两遍——盖树的办法对图要么接受重复、要么付出指数代价。其二，目标不支持的东西必须先补齐：32 位目标上的 64 位加法要拆成两半带进位，这一步叫合法化，发生在覆盖之前。其三，覆盖的决定改变分配的账：激进融合省指令但造出长寿命临时，<a href="/cs/cg-register-allocation-deep">上一课</a>的代价表会把它记回来。</p><p><span class="marginnote">术语翻译：tile 就是「一小片 IR 形状 ↔ 一条机器指令」的模板，比如「加法节点」对应 <code>add</code>，「乘 4 再加」对应 <code>lea</code>；覆盖则是拿这些模板把整棵计算图拼满、不留空隙。选择器的全部工作就是：拼法有很多种，挑总代价最小的那种。</span></p><h3 id="模式从哪来" tabindex="-1">模式从哪来 <a class="header-anchor" href="#模式从哪来" aria-label="Permalink to &quot;模式从哪来&quot;">​</a></h3><p>手写每条指令的匹配规则是不可维护的组合爆炸。工程做法是把指令写成目标描述里的模式——操作码、立即数范围、寻址形式——由 TableGen 这类工具生成匹配器；<a href="/cs/target-description">目标描述</a>一课讲过这套声明式管道。选择器作者维护的是模式库与代价，不是 if-else 森林。另一条谱系把选择当语法分析：指令模式写成文法，覆盖过程就是一次带代价的归约（Glanville–Graham，1978）——骨架不同，问题相同。</p><p><span class="marginnote"><code>lea (%rdi,%rsi,4),%eax</code> 一条指令算出 <code>a+4*b</code>，还不碰 flags——x86 把地址算术做成寻址模式是历史馈赠；RISC 上同一件事是移位加加法两条。选不选得上这个 tile，就是选择器的代价表在说话。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水线分三段。合法化先把 IR 补齐到目标词汇：不支持的类型拆窄，不支持的操作展开或降级为调用；这一步保证覆盖只需要处理「目标会算的东西」。合法化之后做一次目标无关的 DAG 整理，然后进入匹配：主流实现（LLVM 的 SelectionDAG 与 GlobalISel）把图切小块匹配，最优性让位给可预测性，盖得不好的地方留给<a href="/cs/peephole">窥孔</a>在汇编级回收。寻址模式是覆盖最经典的例子：<code>基址+变址*比例+位移</code> 在 x86 上是一个 tile，漏选它就是三条算术。</p><p><span class="marginnote">数字实例：同一个 <code>a + b*4</code>，选上 <code>lea</code> tile 是 1 条指令；RISC 上退成移位加加法 2 条；若连「基址+变址*比例」的寻址模式 tile 也漏选，就要 3 条算术再加一次搬移。tile 挑对与否，同一行源码的指令数能差三倍。</span></p>',12)),(l(),r(n,null,{default:E(()=>[s(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IR%5B%22%E7%9B%AE%E6%A0%87%E6%97%A0%E5%85%B3%20IR%20%E7%9A%84%20DAG%22%5D%20--%3E%20LEG%5B%22%E5%90%88%E6%B3%95%E5%8C%96%EF%BC%9A%E6%8B%86%E7%B1%BB%E5%9E%8B%20%2F%20%E5%B1%95%E5%BC%80%E6%93%8D%E4%BD%9C%22%5D%0A%20%20LEG%20--%3E%20OPT%5B%22DAG%20%E7%BA%A7%E6%95%B4%E7%90%86%22%5D%0A%20%20OPT%20--%3E%20MATCH%5B%22%E6%A8%A1%E5%BC%8F%E5%8C%B9%E9%85%8D%EF%BC%9Atile%20%E8%A6%86%E7%9B%96%22%5D%0A%20%20MATCH%20--%3E%20COST%5B%22%E4%BB%A3%E4%BB%B7%E6%9C%80%E5%B0%8F%E5%8C%96%EF%BC%9A%E8%B4%AA%E5%BF%83%E6%88%96%20DP%22%5D%0A%20%20COST%20--%3E%20MI%5B%22%E6%9C%BA%E5%99%A8%E6%8C%87%E4%BB%A4%20%2B%20%E8%99%9A%E6%8B%9F%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20MI%20--%3E%20RA%5B%22%E4%BA%A4%E7%BB%99%E5%AF%84%E5%AD%98%E5%99%A8%E5%88%86%E9%85%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"选择与分配的耦合是相位问题的第一个实例。融合复合指令省下指令与中间值的落存，代价是中间结果活得更久；拆开大表达式，每段区间更短，分配更松。没有免费的覆盖——两个 pass 的总代价才是目标，工程只能各自局部最优，再用窥孔捡残差。选择器输出的是「机器指令 + 虚拟寄存器」而不是汇编：物理寄存器号还空着，留给分配器；这个中间层让选择不必知道寄存器有几个，也让两课的账能分开算。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「指令越少必然越快」，实际上激进融合会让中间结果活得越久、寄存器压力越大；一旦分配器被迫溢出，多出来的 load/store 会把省下的指令加倍吐回去。正确的目标是选择与分配的总账，不是单看指令条数。")],-1)),(l(),r(n,null,{default:E(()=>[s(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20FUSE%5B%22%E8%9E%8D%E5%90%88%E6%88%90%E5%A4%8D%E5%90%88%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20FEW%5B%22%E6%8C%87%E4%BB%A4%E6%95%B0%E4%B8%8B%E9%99%8D%22%5D%0A%20%20FUSE%20--%3E%20LONG%5B%22%E4%B8%AD%E9%97%B4%E7%BB%93%E6%9E%9C%E5%AF%BF%E5%91%BD%E5%8F%98%E9%95%BF%22%5D%0A%20%20LONG%20--%3E%20PRESS%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E5%8E%8B%E5%8A%9B%E4%B8%8A%E5%8D%87%22%5D%0A%20%20PRESS%20--%3E%20SPILL%7B%22%E5%88%86%E9%85%8D%E5%99%A8%E8%A2%AB%E8%BF%AB%E6%BA%A2%E5%87%BA%EF%BC%9F%22%7D%0A%20%20SPILL%20--%3E%7C%22%E6%98%AF%22%7C%20PAY%5B%22%E6%BA%A2%E5%87%BA%E7%9A%84%20load%2Fstore%20%E5%90%90%E5%9B%9E%E6%94%B6%E7%9B%8A%22%5D%0A%20%20SPILL%20--%3E%7C%22%E5%90%A6%22%7C%20WIN%5B%22%E5%87%80%E6%94%B6%E7%9B%8A%E8%90%BD%E8%A2%8B%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不管编码：把指令变成字节是汇编器与反汇编器的合同。硬件的宏融合在 CPU 前端把相邻指令并成内部操作，编译器不知道也受益，不要与编译器侧的融合混为一谈。树匹配与 munch 的逐步机制不在本课重复；中端的强度削减与重组是中端优化课的对象——选择器消费它们的结果，不重做一遍。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>选择是用封闭指令词汇覆盖开放 IR，目标总代价最小。</li><li>树有 DP 最优解；DAG 因共享要重复或近似，工程退到贪心加窥孔。</li><li>合法化在前：先补齐到目标词汇，覆盖只处理目标会算的东西。</li><li>选择造临时、分配付代价：两个 pass 各自局部最优，残差由窥孔回收。</li><li>出处：Aho, Ganapathi and Tjiang, 1989；Glanville and Graham, 1978；Ertl, 1997；LLVM SelectionDAG / GlobalISel 文档。</li></ul>',4))])}const P=A(c,[["render",p]]);export{S as __pageData,P as default};
